1	import { stat } from "node:fs/promises";
2	import { dirname, join } from "node:path";
3	import { app, BrowserWindow, dialog, ipcMain, shell } from "electron";
4	import { createMainTranslator } from "@kaipu/i18n/main";
5	import { IPC_CHANNELS } from "@shared/types";
6	import type {
7	  LocationCheck,
8	  MoveItemRef,
9	  MoveItemsResult,
10	  WorkspaceBusy,
11	  WorkspaceAddResult,
12	  WorkspaceCreateResult,
13	  WorkspaceEditResult,
14	  WorkspaceRelocateResult,
15	  WorkspacePrepareResult,
16	  WorkspaceRemoveResult,
17	  WorkspacesState,
18	  WorkspaceStamp,
19	  WorkspaceSwitchResult,
20	  WorkspaceView,
21	} from "@shared/types/workspaces";
22	import {
23	  getAllLevelSettings,
24	  getAppSettings,
25	  notifyOverridesChanged,
26	  setOverridesSource,
27	  updateAppSettings,
28	} from "../infrastructure/settings-store";
29	import { isOverridableKey, type OverridableKey } from "@shared/settings-scope";
30	import { dragLedger } from "../library/drag-ledger";
31	import { LibraryVault } from "../library/library-vault";
32	import { loadDeviceId } from "../library/tag-repository";
33	import { vaultActivity } from "../library/vault-activity";
34	import { refusalOfError, runMoveGroup } from "./move-group";
35	import { healMoves, moveItem, type MoveSide } from "./move-item";
36	import { uuidv7 } from "../library/tag-repository";
37	import { defaultVaultDirectory, forgetCachedPreferences } from "../library/vault-location";
38	import { StaleWorkspaceError, WorkspaceGate } from "./gate";
39	import { WorkspaceRegistry, type WorkspaceEntry } from "./registry";
40	import { MachineSettingsStore } from "./settings-overrides";
41	import { WorkspaceSettings } from "./workspace-settings";
42	import { PrepareRequests } from "./prepare-windows";
43	import { relocateRefusal, relocateWorkspace } from "./relocate";
44	import { switchWorkspace, type ActiveTransactionDeps } from "./switch-transaction";
45	import { APP_TITLE, composeWindowTitle } from "./window-title";
46	import { toWorkspaceView } from "./workspace-view";
47	
48	/**
49	 * Workspaces in the main process (ADR 0032): the registry, the gate every item-scoped call
50	 * runs through, and the switch transaction with its IPC. `initWorkspaces()` runs once in
51	 * `app.whenReady`, before any window exists, so the preload can read the stamp at load.
52	 */
53	
54	/** How long a window may take to prepare (an unsaved editor waits on the user's answer). */
55	const PREPARE_TIMEOUT_MS = 120_000;
56	
57	let registry: WorkspaceRegistry | null = null;
58	let gate: WorkspaceGate | null = null;
59	let workspaceSettings: WorkspaceSettings | null = null;
60	
61	export interface WorkspaceHost {
62	  /** What is writing into the active workspace (the switch lock). A move is added here. */
63	  busy(): "recording" | "exporting" | null;
64	  /** Dismiss the capture toast and drop the retained quiet-capture bytes. */
65	  dropPendingCaptures(): void;
66	  /** Re-list every window's library (`library:changed`). */
67	  broadcastLibraryChanged(): void;
68	}
69	
70	let host: WorkspaceHost | null = null;
71	
72	/** The group move running now, if any: it holds the switch lock from its first item to its last. */
73	let moveRun: { stop: boolean } | null = null;
74	
75	/** What locks the switcher right now. */
76	function busyNow(): WorkspaceBusy | null {
77	  return host?.busy() ?? (moveRun ? "moving" : null);
78	}
79	
80	function requireRegistry(): WorkspaceRegistry {
81	  if (!registry) throw new Error("workspaces: not initialized");
82	  return registry;
83	}
84	
85	export function workspaceGate(): WorkspaceGate {
86	  if (!gate) throw new Error("workspaces: not initialized");
87	  return gate;
88	}
89	
90	export async function initWorkspaces(): Promise<void> {
91	  registry = await WorkspaceRegistry.open({
92	    preferencesFile: join(app.getPath("userData"), "preferences.json"),
93	    defaultDirectory: defaultVaultDirectory(),
94	    newId: () => uuidv7(),
95	    onPreferencesWritten: forgetCachedPreferences,
96	  });
97	  gate = new WorkspaceGate(registry.active().id);
98	  await initWorkspaceSettings(registry);
99	  // The preload reads the stamp once, synchronously, before the page's scripts run, so it
100	  // is answered from here, before any window can exist.
101	  ipcMain.on(IPC_CHANNELS.workspacesStampSync, (event) => {
102	    event.returnValue = workspaceGate().stamp satisfies WorkspaceStamp;
103	  });
104	  if (registry.readOnly) {
105	    console.warn("[workspaces] preferences.json does not parse: running read-only until restart");
106	  }
107	  // A move the app died in is finished before anything lists either workspace.
108	  await healPendingMoves();
109	}
110	
111	/**
112	 * Per-workspace setting overrides (ADR 0034): the module that owns the two override files, wired
113	 * to the registry and to the settings store, which resolves the effective settings from it.
114	 * The active workspace's folder file is read once here, at app start.
115	 */
116	async function initWorkspaceSettings(reg: WorkspaceRegistry): Promise<void> {
117	  const machine = await MachineSettingsStore.open(
118	    join(app.getPath("userData"), "workspace-settings.json"),
119	  );
120	  const settings = new WorkspaceSettings({
121	    machine,
122	    workspaces: () => reg.entries().map(({ id, name, path }) => ({ id, name, path })),
123	    activeId: () => reg.active().id,
124	    isAvailable: async (id) => (await reg.availability(id)).availability.state === "available",
125	    getAll: getAllLevelSettings,
126	    writeAll: (patch) => {
127	      updateAppSettings(patch);
128	    },
129	    effective: getAppSettings,
130	    changed: notifyOverridesChanged,
131	    now: () => Date.now(),
132	  });
133	  workspaceSettings = settings;
134	  setOverridesSource(() => settings.activeOverrides());
135	  await settings.refresh(reg.active().id);
136	}
137	
138	function requireWorkspaceSettings(): WorkspaceSettings {
139	  if (!workspaceSettings) throw new Error("workspaces: settings not initialized");
140	  return workspaceSettings;
141	}
142	
143	/**
144	 * Read the active workspace's folder overrides again. A capture calls this as it starts, so a
145	 * file a sync changed since the last read is inactive for this capture and not applied unasked
146	 * (ADR 0034, decision 8). A read that fails leaves the overrides inactive.
147	 */
148	export async function refreshActiveWorkspaceSettings(): Promise<void> {
149	  await workspaceSettings?.refresh(requireRegistry().active().id);
150	}
151	
152	function movesJournalDir(): string {
153	  return join(app.getPath("userData"), "workspace-moves");
154	}
155	
156	/** The folder a workspace of a move lives in now, or null while it is not connected. */
157	async function resolveMoveSide(side: MoveSide): Promise<string | null> {
158	  const reg = requireRegistry();
159	  if (!reg.get(side.workspaceId)) return null;
160	  const { availability, id } = await reg.availability(side.workspaceId);
161	  if (availability.state !== "available") return null;
162	  return reg.get(id)?.path ?? null;
163	}
164	
165	/**
166	 * Finish every move the app died in (ADR 0033, decision 6). At startup and before each group.
167	 * An entry whose workspace is not connected waits for a later run.
168	 */
169	async function healPendingMoves(): Promise<void> {
170	  try {
171	    const report = await healMoves({ journalDir: movesJournalDir(), resolve: resolveMoveSide });
172	    if (report.healed > 0) host?.broadcastLibraryChanged();
173	    if (report.quarantined.length > 0) {
174	      console.error(
175	        `[workspaces] ${report.quarantined.length} interrupted move(s) need a look; journal kept in`,
176	        movesJournalDir(),
177	      );
178	    }
179	  } catch (error) {
180	    console.error("[workspaces] healing interrupted moves failed", error);
181	  }
182	}
183	
184	let deviceId: Promise<string> | null = null;
185	
186	/**
187	 * `workspaces:move-items`: a group of single moves from the active workspace to `targetId`,
188	 * one after another (ADR 0033, decision 14). Runs inside the workspace gate, so the window's
189	 * stamp must still be current, and holds the switch lock from the first item to the last.
190	 */
191	async function moveItems(
192	  sender: Electron.WebContents,
193	  stamp: unknown,
194	  input: unknown,
195	): Promise<MoveItemsResult> {
196	  const reg = requireRegistry();
197	  const { items: rawItems, targetId } = (input ?? {}) as { items?: unknown; targetId?: unknown };
198	  const items: MoveItemRef[] = Array.isArray(rawItems)
199	    ? rawItems.filter(
200	        (item): item is MoveItemRef =>
201	          !!item &&
202	          typeof (item as MoveItemRef).id === "string" &&
203	          typeof (item as MoveItemRef).assetId === "string",
204	      )
205	    : [];
206	  const target = typeof targetId === "string" ? targetId : "";
207	  const refuseAll = (reason: MoveItemsResult["failed"][number]["reason"]): MoveItemsResult => ({
208	    targetId: target,
209	    moved: [],
210	    failed: items.map((item) => ({ id: item.id, reason })),
211	    skipped: [],
212	  });
213	  if (moveRun) return refuseAll("busy");
214	  if (!workspaceGate().isCurrent(stamp)) return refuseAll("stale");
215	  if (vaultActivity.inMaintenance) return refuseAll("maintenance");
216	
217	  const run = { stop: false };
218	  moveRun = run;
219	  void broadcastState();
220	  try {
221	    return await workspaceGate().run(stamp, () =>
222	      vaultActivity.run("library", async () => {
223	        await healPendingMoves();
224	        const source = reg.active();
225	        // A rejected read is not kept: the next group asks again.
226	        deviceId ??= loadDeviceId(app.getPath("userData")).catch((error: unknown) => {
227	          deviceId = null;
228	          throw error;
229	        });
230	        const device = await deviceId;
231	        const result = await runMoveGroup(
232	          items,
233	          async (item) => {
234	            // Checked per item, when its turn comes (decision 14).
235	            if (host?.busy()) return { ok: false, reason: "busy" };
236	            if (target === source.id) return { ok: false, reason: "same-workspace" };
237	            const entry = reg.get(target);
238	            if (!entry) return { ok: false, reason: "target-unavailable" };
239	            const directory = await resolveMoveSide({ workspaceId: target, directory: "" });
240	            if (directory === null) return { ok: false, reason: "target-unavailable" };
241	            const outcome = await moveItem(
242	              {
243	                source: { workspaceId: source.id, directory: source.path },
244	                target: { workspaceId: target, directory },
245	                id: item.id,
246	                expectedAssetId: item.assetId,
247	              },
248	              { journalDir: movesJournalDir(), deviceId: () => device, dragLedger },
249	            );
250	            return outcome.ok
251	              ? { ok: true, newId: outcome.newId }
252	              : { ok: false, reason: outcome.reason };
253	          },
254	          {
255	            targetId: target,
256	            stopped: () => run.stop,
257	            onProgress: (progress) => {
258	              if (!sender.isDestroyed()) {
259	                sender.send(IPC_CHANNELS.workspacesMoveProgress, progress);
260	              }
261	            },
262	          },
263	        );
264	        return result;
265	      }),
266	    );
267	  } catch (error) {
268	    console.error("[workspaces] group move refused", error);
269	    return refuseAll(refusalOfError(error));
270	  } finally {
271	    moveRun = null;
272	    host?.broadcastLibraryChanged();
273	    void broadcastState();
274	  }
275	}
276	
277	export function activeWorkspace(): WorkspaceEntry {
278	  return requireRegistry().active();
279	}
280	
281	/** Owns the cloud entries without a workspace id (spec decision 3): only it lists them. */
282	export function ownsLegacyCloud(): boolean {
283	  const reg = requireRegistry();
284	  return reg.active().id === reg.state.legacyCloudOwnerId;
285	}
286	
287	/** The workspace's name for a label, only once a second one exists (window title, tray). */
288	function prefixName(): string | null {
289	  const reg = requireRegistry();
290	  return reg.entries().length > 1 ? reg.active().name : null;
291	}
292	
293	/** The capture target was unplugged or replaced: refuse, never save anywhere else. */
294	export class WorkspaceNotConnectedError extends Error {
295	  constructor(readonly workspaceName: string) {
296	    const t = createMainTranslator(getAppSettings().locale);
297	    super(t("workspaces.notConnectedError", { name: workspaceName }));
298	    this.name = "WorkspaceNotConnectedError";
299	  }
300	}
301	
302	/**
303	 * The active workspace, checked to be connected, for a capture that is about to start.
304	 * Throws `WorkspaceNotConnectedError` otherwise; a switch in progress counts as stale.
305	 */
306	export async function requireCaptureWorkspace(): Promise<WorkspaceEntry> {
307	  const reg = requireRegistry();
308	  if (workspaceGate().switching) throw new StaleWorkspaceError();
309	  const active = reg.active();
310	  const { availability, id } = await reg.availability(active.id);
311	  if (workspaceGate().adopt(active.id, id, reg.active().id)) void broadcastState();
312	  if (availability.state !== "available") throw new WorkspaceNotConnectedError(active.name);
313	  await refreshActiveWorkspaceSettings();
314	  return reg.active();
315	}
316	
317	/** Every workspace whose folder is reachable, for the startup and quit sweeps. */
318	export async function availableWorkspacePaths(): Promise<string[]> {
319	  const reg = requireRegistry();
320	  const paths: string[] = [];
321	  // A copy: a probe may update an entry (a pending one adopting its folder's id).
322	  for (const entry of reg.entries().slice()) {
323	    const { availability } = await reg.availability(entry.id);
324	    if (availability.state === "available") paths.push(entry.path);
325	  }
326	  return paths;
327	}
328	
329	async function listState(): Promise<WorkspacesState> {
330	  const reg = requireRegistry();
331	  const views: WorkspaceView[] = [];
332	  for (const entry of reg.entries().slice()) {
333	    const { availability, id } = await reg.availability(entry.id);
334	    // A pending active entry that adopted its folder's id: windows must take the new stamp.
335	    if (workspaceGate().adopt(entry.id, id, reg.active().id)) void broadcastState();
336	    const count =
337	      availability.state === "available"
338	        ? await new LibraryVault(entry.path).countMedia().catch(() => null)
339	        : null;
340	    // Which volume the folder is on: "Move to" says whether a move copies or is instant.
341	    const device =
342	      availability.state === "available"
343	        ? await stat(entry.path).then(
344	            (info) => String(info.dev),
345	            () => null,
346	          )
347	        : null;
348	    views.push(toWorkspaceView(reg.get(id) ?? entry, availability, count, device));
349	  }
350	  const { activeId, hintDismissedAt } = reg.state;
351	  return {
352	    activeId,
353	    generation: workspaceGate().stamp.generation,
354	    hintDismissed: hintDismissedAt !== undefined,
355	    busy: busyNow(),
356	    readOnly: reg.readOnly,
357	    workspaces: views,
358	  };
359	}
360	
361	function sendToAll(channel: string, payload?: unknown): void {
362	  for (const window of BrowserWindow.getAllWindows()) {
363	    if (!window.isDestroyed()) window.webContents.send(channel, payload);
364	  }
365	}
366	
367	async function broadcastState(): Promise<void> {
368	  sendToAll(IPC_CHANNELS.workspacesChanged, await listState());
369	}
370	
371	/** The main window's title follows the active workspace and the page's own title. */
372	export function attachWindowTitle(window: BrowserWindow): void {
373	  let pageTitle = APP_TITLE;
374	  const apply = (): void => {
375	    if (!window.isDestroyed()) window.setTitle(composeWindowTitle(pageTitle, prefixName()));
376	  };
377	  window.on("page-title-updated", (event, title) => {
378	    event.preventDefault();
379	    pageTitle = title;
380	    apply();
381	  });
382	  titleAppliers.add(apply);
383	  window.on("closed", () => titleAppliers.delete(apply));
384	  apply();
385	}
386	
387	const titleAppliers = new Set<() => void>();
388	
389	function refreshTitles(): void {
390	  for (const apply of titleAppliers) apply();
391	}
392	
393	const prepareRequests = new PrepareRequests(IPC_CHANNELS.workspacesPrepare, PREPARE_TIMEOUT_MS);
394	
395	/** What every change to the active workspace shares: the lock, the windows, the commit. */
396	function activeTransactionDeps(): ActiveTransactionDeps {
397	  return {
398	    gate: workspaceGate(),
399	    // The group move holds this lock too: a folder cannot change under it.
400	    busy: busyNow,
401	    prepareWindows: () => prepareRequests.prepare(BrowserWindow.getAllWindows()),
402	    abortWindows: () => sendToAll(IPC_CHANNELS.workspacesPrepareAbort),
403	    dropPendingCaptures: () => host?.dropPendingCaptures(),
404	    afterCommit: () => {
405	      // The new workspace's effective settings reach every window and every main listener.
406	      notifyOverridesChanged();
407	      refreshTitles();
408	      void broadcastState();
409	      host?.broadcastLibraryChanged();
410	    },
411	  };
412	}
413	
414	async function runSwitch(id: string): Promise<WorkspaceSwitchResult> {
415	  const reg = requireRegistry();
416	  const result = await switchWorkspace(
417	    {
418	      ...activeTransactionDeps(),
419	      activeId: () => reg.active().id,
420	      isKnown: (candidate) => reg.get(candidate) !== undefined,
421	      readOnly: () => reg.readOnly,
422	      availability: (candidate) => reg.availability(candidate),
423	      persistActive: async (target) => {
424	        await reg.setActive(target);
425	        // The target's overrides are read before the switch is certain, so the effective
426	        // settings are ready the moment it commits. A read that fails leaves them inactive.
427	        await workspaceSettings?.refresh(target);
428	      },
429	    },
430	    id,
431	  );
432	  // A refused switch still re-lists, so a LOCKED or NOT CONNECTED menu shows why.
433	  if (!result.ok) void broadcastState();
434	  return result;
435	}
436	
437	/** Folder picker for Add workspace; initializes or adopts the folder, then switches to it. */
438	async function addWorkspace(
439	  sender: Electron.WebContents,
440	  request: { activate?: unknown } = {},
441	): Promise<WorkspaceAddResult> {
442	  const reg = requireRegistry();
443	  if (reg.readOnly) return { ok: false, reason: "read-only" };
444	  const window = BrowserWindow.fromWebContents(sender);
445	  const t = createMainTranslator(getAppSettings().locale);
446	  const options: Electron.OpenDialogOptions = {
447	    title: t("dialogs.addWorkspace"),
448	    buttonLabel: t("dialogs.addWorkspaceButton"),
449	    properties: ["openDirectory", "createDirectory"],
450	  };
451	  const picked = window
452	    ? await dialog.showOpenDialog(window, options)
453	    : await dialog.showOpenDialog(options);
454	  const chosen = picked.filePaths[0];
455	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
456	
457	  const outcome = await reg.add(chosen);
458	  if (!outcome.ok) {
459	    if (outcome.reason !== "read-only") {
460	      const message = { type: "error" as const, message: t("dialogs.folderUnusable") };
461	      const detail = t(
462	        outcome.reason === "unreadable"
463	          ? "dialogs.workspaceUnreadableDetail"
464	          : "dialogs.folderUnusableDetail",
465	      );
466	      await (window
467	        ? dialog.showMessageBox(window, { ...message, detail })
468	        : dialog.showMessageBox({ ...message, detail }));
469	    }
470	    return { ok: false, reason: outcome.reason === "read-only" ? "read-only" : "not-writable" };
471	  }
472	  // Adding a workspace answers the "New: workspaces" hint too.
473	  await reg.dismissHint();
474	  const { availability } = await reg.availability(outcome.entry.id);
475	  // An adopted folder may bring its own settings file: read it now, so it shows as pending.
476	  await workspaceSettings?.refresh(outcome.entry.id);
477	  // Then make it the active one, through the same transaction as any other switch. A
478	  // refusal (a recording running) leaves it registered and inactive. "Move to ▸ New
479	  // workspace…" keeps it inactive: the item goes there, the user stays here.
480	  if (request.activate !== false) await runSwitch(outcome.entry.id);
481	  await broadcastState();
482	  return { ok: true, workspace: toWorkspaceView(outcome.entry, availability, null) };
483	}
484	
485	/**
486	 * New workspace: a new folder next to the Default workspace's, only Kaipu's files in it, then
487	 * the same switch as any other. A refused switch (a recording running) leaves it registered.
488	 */
489	async function createWorkspace(input: unknown): Promise<WorkspaceCreateResult> {
490	  const reg = requireRegistry();
491	  const { name, color, activate } = (input ?? {}) as {
492	    name?: unknown;
493	    color?: unknown;
494	    activate?: unknown;
495	  };
496	  if (typeof name !== "string") return { ok: false, reason: "invalid-name" };
497	  if (typeof color !== "string") return { ok: false, reason: "invalid-color" };
498	  const outcome = await reg.create({ name, color });
499	  if (!outcome.ok) return outcome;
500	  await reg.dismissHint();
501	  const { availability } = await reg.availability(outcome.entry.id);
502	  // "Move to ▸ New workspace…" creates it inactive: the item goes there, the user stays here.
503	  const switchResult: WorkspaceSwitchResult =
504	    activate === false ? { ok: true } : await runSwitch(outcome.entry.id);
505	  await broadcastState();
506	  return {
507	    ok: true,
508	    workspace: toWorkspaceView(outcome.entry, availability, null),
509	    switchResult,
510	  };
511	}
512	
513	async function editWorkspace(input: unknown): Promise<WorkspaceEditResult> {
514	  const reg = requireRegistry();
515	  const { id, name, color } = (input ?? {}) as { id?: unknown; name?: unknown; color?: unknown };
516	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
517	  const outcome = await reg.edit(id, {
518	    ...(typeof name === "string" ? { name } : {}),
519	    ...(typeof color === "string" ? { color } : {}),
520	  });
521	  if (!outcome.ok) return outcome;
522	  const { availability } = await reg.availability(outcome.entry.id);
523	  // The window title shows the active workspace's name, and the tiles show the initials.
524	  refreshTitles();
525	  await broadcastState();
526	  return {
527	    ok: true,
528	    workspace: toWorkspaceView(outcome.entry, availability, null),
529	    savedToFolder: outcome.savedToFolder,
530	  };
531	}
532	
533	function overridableKeys(value: unknown): OverridableKey[] | null {
534	  if (!Array.isArray(value) || !value.every(isOverridableKey)) return null;
535	  return value;
536	}
537	
538	/** `settings:*` channels for the other levels (ADR 0034). The generic ones stay in settings-store. */
539	function registerSettingsScopeHandlers(): void {
540	  ipcMain.handle(IPC_CHANNELS.settingsGetScoped, (_event, scope: unknown) =>
541	    requireWorkspaceSettings().getScoped(typeof scope === "string" ? scope : "all"),
542	  );
543	  ipcMain.handle(
544	    IPC_CHANNELS.settingsSetOverride,
545	    (_event, workspaceId: unknown, key: unknown, value: unknown) =>
546	      typeof workspaceId === "string" && isOverridableKey(key)
547	        ? requireWorkspaceSettings().setOverride(workspaceId, key, value ?? null)
548	        : { ok: false, reason: "not-overridable" },
549	  );
550	  ipcMain.handle(
551	    IPC_CHANNELS.settingsResetOverrides,
552	    (_event, workspaceId: unknown, keys: unknown) => {
553	      const checked = overridableKeys(keys);
554	      return typeof workspaceId === "string" && checked
555	        ? requireWorkspaceSettings().resetOverrides(workspaceId, checked)
556	        : { ok: false, reason: "not-overridable" };
557	    },
558	  );
559	  ipcMain.handle(IPC_CHANNELS.settingsCopyToAll, (_event, workspaceId: unknown, keys: unknown) => {
560	    const checked = overridableKeys(keys);
561	    return typeof workspaceId === "string" && checked
562	      ? requireWorkspaceSettings().copyToAll(workspaceId, checked)
563	      : { ok: false, reason: "not-overridable" };
564	  });
565	  ipcMain.handle(
566	    IPC_CHANNELS.settingsResolvePending,
567	    (_event, workspaceId: unknown, decision: unknown, sha256: unknown) =>
568	      typeof workspaceId === "string" &&
569	      (decision === "use" || decision === "ignore") &&
570	      typeof sha256 === "string"
571	        ? requireWorkspaceSettings().resolvePending(workspaceId, decision, sha256)
572	        : { ok: false, reason: "nothing-pending" },
573	  );
574	}
575	
576	/**
577	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
578	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
579	 */
580	async function relocateFolder(
581	  sender: Electron.WebContents,
582	  id: unknown,
583	): Promise<WorkspaceRelocateResult> {
584	  const reg = requireRegistry();
585	  const deps = { ...activeTransactionDeps(), registry: reg };
586	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
587	  // Locked or read-only: say so now, instead of after the user picked a folder.
588	  const refused = relocateRefusal(deps, id);
589	  if (refused) return refused;
590	  const entry = reg.get(id);
591	  if (!entry) return { ok: false, reason: "unknown" };
592	
593	  const window = BrowserWindow.fromWebContents(sender);
594	  const t = createMainTranslator(getAppSettings().locale);
595	  const options: Electron.OpenDialogOptions = {
596	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
597	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
598	    // Where it was: a moved folder is usually next to where it used to be.
599	    defaultPath: dirname(entry.path),
600	    properties: ["openDirectory", "createDirectory"],
601	  };
602	  const picked = window
603	    ? await dialog.showOpenDialog(window, options)
604	    : await dialog.showOpenDialog(options);
605	  const chosen = picked.filePaths[0];
606	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
607	
608	  const outcome = await relocateWorkspace(deps, id, chosen);
609	  if (!outcome.ok) return outcome;
610	  const { availability } = await reg.availability(outcome.entry.id);
611	  // The active workspace re-lists inside its transaction; any other one only needs the state.
612	  refreshTitles();
613	  await broadcastState();
614	  return {
615	    ok: true,
616	    workspace: toWorkspaceView(reg.get(outcome.entry.id) ?? outcome.entry, availability, null),
617	    ...(outcome.unchanged ? { unchanged: true as const } : {}),
618	  };
619	}
620	
621	export function registerWorkspaceHandlers(deps: WorkspaceHost): void {
622	  host = deps;
623	  registerSettingsScopeHandlers();
624	  ipcMain.handle(IPC_CHANNELS.workspacesList, () => listState());
625	  ipcMain.handle(IPC_CHANNELS.workspacesSwitch, (_event, id: unknown) =>
626	    typeof id === "string" ? runSwitch(id) : { ok: false, reason: "unknown" },
627	  );
628	  ipcMain.handle(IPC_CHANNELS.workspacesAdd, (event, options: unknown) =>
629	    addWorkspace(event.sender, (options ?? {}) as { activate?: unknown }),
630	  );
631	  ipcMain.handle(IPC_CHANNELS.workspacesMoveItems, (event, stamp: unknown, input: unknown) =>
632	    moveItems(event.sender, stamp, input),
633	  );
634	  ipcMain.handle(IPC_CHANNELS.workspacesCancelMove, () => {
635	    if (moveRun) moveRun.stop = true;
636	  });
637	  ipcMain.handle(IPC_CHANNELS.workspacesCreate, (_event, input: unknown) => createWorkspace(input));
638	  ipcMain.handle(IPC_CHANNELS.workspacesEdit, (_event, input: unknown) => editWorkspace(input));
639	  ipcMain.handle(IPC_CHANNELS.workspacesRelocate, (event, id: unknown) =>
640	    relocateFolder(event.sender, id),
641	  );
642	  ipcMain.handle(
643	    IPC_CHANNELS.workspacesCheckLocation,
644	    (_event, name: unknown): Promise<LocationCheck> =>
645	      typeof name === "string"
646	        ? requireRegistry().checkNewLocation(name)
647	        : Promise.resolve({ path: null, state: "parent-missing" }),
648	  );
649	  ipcMain.handle(
650	    IPC_CHANNELS.workspacesRemove,
651	    async (_event, id: unknown): Promise<WorkspaceRemoveResult> => {
652	      if (typeof id !== "string") return { ok: false, reason: "unknown" };
653	      const result = await requireRegistry().remove(id);
654	      if (result.ok) {
655	        refreshTitles();
656	        await broadcastState();
657	      }
658	      return result;
659	    },
660	  );
661	  ipcMain.handle(IPC_CHANNELS.workspacesOpenFolder, async (_event, id: unknown) => {
662	    const entry = typeof id === "string" ? requireRegistry().get(id) : undefined;
663	    if (!entry) return;
664	    // shell.openPath never creates the folder: a missing one reports an error string.
665	    const error = await shell.openPath(entry.path);
666	    if (error) console.error("failed to open the workspace folder", error);
667	  });
668	  ipcMain.handle(IPC_CHANNELS.workspacesDismissHint, async () => {
669	    await requireRegistry().dismissHint();
670	    await broadcastState();
671	  });
672	  ipcMain.on(IPC_CHANNELS.workspacesPrepareResult, (_event, result: WorkspacePrepareResult) => {
673	    if (!result || typeof result.requestId !== "number") return;
674	    prepareRequests.answer(result.requestId, result.ok === true);
675	  });
676	}
677	
678	/** Re-list the switcher in every window (the lock changed: a take started or ended). */
679	export function notifyWorkspaceBusyChanged(): void {
680	  if (registry && gate) void broadcastState();
681	}
