180	 * mode, and that must not re-register every global shortcut or rebuild the tray menu.
181	 */
182	export function onSettingsKeysChanged<K extends keyof AppSettings>(
183	  keys: readonly K[],
184	  listener: (settings: AppSettings) => void,
185	): void {
186	  const snapshot = (from: AppSettings): string => JSON.stringify(keys.map((key) => from[key]));
187	  let seen = snapshot(effective);
188	  settingsListeners.add((next) => {
189	    const now = snapshot(next);
190	    if (now === seen) return;
191	    seen = now;
192	    listener(next);
193	  });
194	}
195	
196	/** The launch-at-login value last handed to the OS; `null` before the first. */
197	let appliedLaunchAtLogin: boolean | null = null;
198	
199	function applySideEffects(): void {
200	  applyDockPolicy();
201	  // Only on a change: the OS call writes the login item each time, and every settings write
202	  // (a mode chip, a remembered frame) used to repeat it.
203	  if (
204	    (process.platform === "darwin" || process.platform === "win32") &&
205	    settings.launchAtLogin !== appliedLaunchAtLogin
206	  ) {
207	    appliedLaunchAtLogin = settings.launchAtLogin;
208	    app.setLoginItemSettings({ openAtLogin: settings.launchAtLogin });
209	  }
210	}
211	
212	/**
213	 * Merge `patch` into the persisted settings, then persist, apply side effects, notify
214	 * main listeners and broadcast to every window: the same path the renderer's
215	 * `updateSettings` takes, for main-side writers (a mode-specific capture shortcut).
216	 */
217	export function updateAppSettings(patch: Partial<AppSettings>): AppSettings {
218	  settings = mergeSettings({ ...settings, ...patch });
219	  persist();
220	  applySideEffects();
221	  recomputeEffective();
222	  for (const listener of settingsListeners) listener(effective);
223	  broadcastSettings();
224	  return effective;
225	}
226	
227	/**
228	 * The active workspace's overrides changed (a switch, a capture start that found the folder
229	 * file edited, an override written or answered): recompute the effective settings, wake the
230	 * listeners of the keys that changed and broadcast the new snapshot to every window.
231	 */
